import React, { useState, useEffect } from 'react';
import { 
  StyleSheet, Text, View, TextInput, TouchableOpacity, 
    FlatList, SafeAreaView, StatusBar, Alert 
    } from 'react-native';
    import AsyncStorage from '@react-native-async-storage/async-storage';

    export default function App() {
      const [exercise, setExercise] = useState('');
        const [sets, setSets] = useState('');
          const [reps, setReps] = useState('');
            const [weight, setWeight] = useState('');
              const [workouts, setWorkouts] = useState([]);

                // Wczytanie zapisanych treningów z pamięci telefonu przy uruchomieniu
                  useEffect(() => {
                      loadWorkouts();
                        }, []);

                          const saveWorkoutsToStorage = async (data) => {
                              try {
                                    await AsyncStorage.setItem('@workouts_list', JSON.stringify(data));
                                        } catch (e) {
                                              console.error('Błąd zapisu danych', e);
                                                  }
                                                    };

                                                      const loadWorkouts = async () => {
                                                          try {
                                                                const savedData = await AsyncStorage.getItem('@workouts_list');
                                                                      if (savedData !== null) {
                                                                              setWorkouts(JSON.parse(savedData));
                                                                                    }
                                                                                        } catch (e) {
                                                                                              console.error('Błąd odczytu danych', e);
                                                                                                  }
                                                                                                    };

                                                                                                      const addWorkout = () => {
                                                                                                          if (!exercise.trim()) {
                                                                                                                Alert.alert('Błąd', 'Wpisz nazwę ćwiczenia!');
                                                                                                                      return;
                                                                                                                          }

                                                                                                                              const newEntry = {
                                                                                                                                    id: Date.now().toString(),
                                                                                                                                          date: new Date().toLocaleDateString('pl-PL'),
                                                                                                                                                exercise: exercise,
                                                                                                                                                      sets: sets || '0',
                                                                                                                                                            reps: reps || '0',
                                                                                                                                                                  weight: weight || '0',
                                                                                                                                                                      };

                                                                                                                                                                          const updatedWorkouts = [newEntry, ...workouts];
                                                                                                                                                                              setWorkouts(updatedWorkouts);
                                                                                                                                                                                  saveWorkoutsToStorage(updatedWorkouts);

                                                                                                                                                                                      // Czyszczenie pól formularza
                                                                                                                                                                                          setExercise('');
                                                                                                                                                                                              setSets('');
                                                                                                                                                                                                  setReps('');
                                                                                                                                                                                                      setWeight('');
                                                                                                                                                                                                        };

                                                                                                                                                                                                          const deleteWorkout = (id) => {
                                                                                                                                                                                                              const updatedWorkouts = workouts.filter(item => item.id !== id);
                                                                                                                                                                                                                  setWorkouts(updatedWorkouts);
                                                                                                                                                                                                                      saveWorkoutsToStorage(updatedWorkouts);
                                                                                                                                                                                                                        };

                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                              <SafeAreaView style={styles.container}>
                                                                                                                                                                                                                                    <StatusBar barStyle="light-content" backgroundColor="#1e1e2d" />
                                                                                                                                                                                                                                          <Text style={styles.header}>Dziennik Treningowy</Text>

                                                                                                                                                                                                                                                {/* Formularz dodawania */}
                                                                                                                                                                                                                                                      <View style={styles.formContainer}>
                                                                                                                                                                                                                                                              <TextInput
                                                                                                                                                                                                                                                                        style={styles.input}
                                                                                                                                                                                                                                                                                  placeholder="Nazwa ćwiczenia (np. Wyciskanie)"
                                                                                                                                                                                                                                                                                            placeholderTextColor="#aaa"
                                                                                                                                                                                                                                                                                                      value={exercise}
                                                                                                                                                                                                                                                                                                                onChangeText={setExercise}
                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                <View style={styles.row}>
                                                                                                                                                                                                                                                                                                                                          <TextInput
                                                                                                                                                                                                                                                                                                                                                      style={[styles.input, styles.flex1]}
                                                                                                                                                                                                                                                                                                                                                                  placeholder="Serie"
                                                                                                                                                                                                                                                                                                                                                                              placeholderTextColor="#aaa"
                                                                                                                                                                                                                                                                                                                                                                                          keyboardType="numeric"
                                                                                                                                                                                                                                                                                                                                                                                                      value={sets}
                                                                                                                                                                                                                                                                                                                                                                                                                  onChangeText={setSets}
                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                      <TextInput
                                                                                                                                                                                                                                                                                                                                                                                                                                                  style={[styles.input, styles.flex1, styles.marginHorizontal]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                              placeholder="Powtórzenia"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholderTextColor="#aaa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      keyboardType="numeric"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={reps}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChangeText={setReps}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TextInput
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={[styles.input, styles.flex1]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholder="Ciężar (kg)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      placeholderTextColor="#aaa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  keyboardType="numeric"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              value={weight}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChangeText={setWeight}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={styles.button} onPress={addWorkout}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={styles.buttonText}>+ DODAJ TRENING</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* Lista zapisanych treningów */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                data={workouts}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        keyExtractor={(item) => item.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderItem={({ item }) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={styles.card}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={styles.cardTitle}>{item.exercise}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={styles.cardSubtitle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {item.date} | {item.sets} serii x {item.reps} powt. ({item.weight} kg)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity onPress={() => deleteWorkout(item.id)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.deleteText}>Usuń</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ListEmptyComponent={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.emptyText}>Brak zapisanych treningów. Dodaj swój pierwszy!</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </SafeAreaView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            container: { flex: 1, backgroundColor: '#121212', padding: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              header: { fontSize: 24, fontWeight: 'bold', color: '#fff', textAlign: 'center', marginVertical: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formContainer: { backgroundColor: '#1e1e2d', padding: 16, borderRadius: 12, marginBottom: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  input: { backgroundColor: '#2a2a3c', color: '#fff', padding: 12, borderRadius: 8, marginBottom: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    row: { flexDirection: 'row', justifyContent: 'space-between' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      flex1: { flex: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        marginHorizontal: { marginHorizontal: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          button: { backgroundColor: '#bb86fc', padding: 14, borderRadius: 8, alignItems: 'center', marginTop: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            buttonText: { color: '#000', fontWeight: 'bold', fontSize: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              card: { 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  backgroundColor: '#1e1e2d', padding: 16, borderRadius: 12, marginBottom: 10, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          cardTitle: { color: '#fff', fontSize: 18, fontWeight: 'bold' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cardSubtitle: { color: '#aaa', fontSize: 14, marginTop: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              deleteText: { color: '#ff5555', fontWeight: 'bold' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                emptyText: { color: '#666', textAlign: 'center', marginTop: 40, fontSize: 16 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                